const money = (value: number | string) => `₹${Number(value).toLocaleString("en-IN", { maximumFractionDigits: 0 })}`;
const loadRazorpay = () => new Promise<void>((resolve, reject) => { if ((window as any).Razorpay) return resolve(); const script = document.createElement("script"); script.src = "https://checkout.razorpay.com/v1/checkout.js"; script.onload = () => resolve(); script.onerror = () => reject(new Error("Razorpay checkout could not load")); document.body.appendChild(script); });
const imagesOf = (product: Product) => typeof product.images === "string" ? JSON.parse(product.images) as string[] : product.images;
const finalPrice = (product: Product) => Number(product.price) * (1 - Number(product.discount) / 100);
const initials = (value?: string | null) => (value || "Guest").split(" ").map(part => part[0]).join("").slice(0, 2).toUpperCase();

async function optimizeImage(file: File) {
  if (!file.type.startsWith("image/") || file.type === "image/avif") return file;
  const bitmap = await createImageBitmap(file);
  const scale = Math.min(1, 1600 / Math.max(bitmap.width, bitmap.height));
  const canvas = document.createElement("canvas"); canvas.width = Math.max(1, Math.round(bitmap.width * scale)); canvas.height = Math.max(1, Math.round(bitmap.height * scale));
  canvas.getContext("2d")?.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
  const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, "image/webp", 0.86));
  bitmap.close();
  return blob ? new File([blob], `${file.name.replace(/\.[^.]+$/, "")}.webp`, { type: "image/webp" }) : file;
}

async function uploadMediaFile(file: File) {
  const prepared = await optimizeImage(file);
  const token = sessionStorage.getItem("horologe-session");
  const response = await fetch("/api/store/media", { method: "POST", headers: { "Content-Type": prepared.type, "X-File-Name": prepared.name, ...(token ? { Authorization: `Bearer ${token}` } : {}) }, body: prepared });
  const data = await response.json() as { url?: string; error?: string };
  if (!response.ok || !data.url) throw new Error(data.error || "Media upload failed");
  return data.url;
}

function MediaUpload({ label, accept, onUploaded }: { label: string; accept: string; onUploaded: (url: string) => void }) {
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const handleChange = async (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; setBusy(true); setMessage(""); try { onUploaded(await uploadMediaFile(file)); setMessage("Uploaded to CDN storage"); } catch (error) { setMessage(error instanceof Error ? error.message : "Upload failed"); } finally { setBusy(false); event.target.value = ""; } };
  return <label className="media-upload">{label}<input type="file" accept={accept} onChange={handleChange} disabled={busy} /><small>{busy ? "Optimizing and uploading…" : message || "Optimized CDN upload"}</small></label>;
}

