function ProductCard({ product, onAdd, adding, isSaved, onWishlist }: { product: Product; onAdd: (product: Product) => void; adding?: boolean; isSaved?: boolean; onWishlist?: (product: Product) => void }) {
  const image = imagesOf(product)[0];
  const discounted = Number(product.discount) > 0;
  return <article className="product-card">
    <Link href={`/products/${product.id}`} className="product-image-wrap"><img src={image} alt={product.name} />{discounted && <span className="sale-badge">-{Number(product.discount)}%</span>}</Link>
    <div className="product-card-body"><div className="product-card-top"><div><Link href={`/products/${product.id}`} className="product-name">{product.name}</Link></div><button className={`heart-button ${isSaved ? "is-saved" : ""}`} aria-label={`${isSaved ? "Remove" : "Save"} ${product.name}`} onClick={() => onWishlist?.(product)}><Heart size={17} fill={isSaved ? "currentColor" : "none"} /></button></div><p className="product-short">{product.shortDescription}</p><div className="product-card-footer"><div className="price-stack">{discounted && <span className="original-price">{money(product.price)}</span>}<span className="final-price">{money(finalPrice(product))}</span>{discounted && <span className="discount-note">Save {money(Number(product.price) - finalPrice(product))}</span>}</div><button className={`add-button ${adding ? "is-loading" : ""}`} onClick={() => onAdd(product)} disabled={adding || product.stock === 0}>{adding ? <><span className="button-spinner" /> Adding</> : product.stock === 0 ? "Sold out" : "Add to bag"}</button></div><div className={`stock-line ${product.stock < 8 ? "low" : ""}`}><span className="stock-dot" />{product.stock === 0 ? "Sold out" : product.stock < 8 ? `Only ${product.stock} left` : `${product.stock} available`}</div></div>
  </article>;
}

