function ProductsPage({ products, brands, onAdd, addingId, savedIds, onWishlist }: { products: Product[]; brands: Brand[]; onAdd: (p: Product) => void; addingId?: number | null; savedIds?: Set<number>; onWishlist?: (p: Product) => void }) {
  const [location] = useLocation();
  const query = new URLSearchParams(location.split("?")[1] || "");
  const [collection, setCollection] = useState(query.get("collection") || "all");
  const [sort, setSort] = useState("featured"); const [brandId, setBrandId] = useState("all"); const [minPrice, setMinPrice] = useState(""); const [maxPrice, setMaxPrice] = useState(""); const [videoOnly, setVideoOnly] = useState(false);
  const filtered = useMemo(() => { const source = products.filter(p => (collection === "all" || p.collection === collection) && (brandId === "all" || p.brandId === Number(brandId)) && (!minPrice || finalPrice(p) >= Number(minPrice)) && (!maxPrice || finalPrice(p) <= Number(maxPrice)) && (!videoOnly || Boolean(p.videoUrl))); return [...source].sort((a, b) => sort === "price-low" ? finalPrice(a) - finalPrice(b) : sort === "price-high" ? finalPrice(b) - finalPrice(a) : sort === "name" ? a.name.localeCompare(b.name) : a.id - b.id); }, [products, collection, sort, brandId, minPrice, maxPrice, videoOnly]);
  return <section className="listing container"><div className="listing-heading"><div><p className="eyebrow">THE COLLECTION</p><h1>Timepieces for<br /><em>every hour.</em></h1></div><p className="listing-note">A considered edit of automatic and quartz watches, designed in our studio and made to become yours.</p></div><div className="brand-directory"><div className="brand-directory-head"><span className="eyebrow">BRANDS</span><span>Browse by house</span></div><div className="brand-directory-grid">{brands.map(brand => <button className={brandId === String(brand.id) ? "active" : ""} key={brand.id} onClick={() => setBrandId(brandId === String(brand.id) ? "all" : String(brand.id))}><img src={brand.image} alt="" /><span><strong>{brand.title}</strong><small>{brand.description}</small></span></button>)}</div></div><div className="filter-bar"><div className="filter-tabs"><button className={collection === "all" ? "selected" : ""} onClick={() => setCollection("all")}>All</button><button className={collection === "men" ? "selected" : ""} onClick={() => setCollection("men")}>For him</button><button className={collection === "women" ? "selected" : ""} onClick={() => setCollection("women")}>For her</button></div><div className="browse-controls"><label className="filter-control"><span>Brand</span><select value={brandId} onChange={e => setBrandId(e.target.value)}><option value="all">All brands</option>{brands.map(brand => <option key={brand.id} value={brand.id}>{brand.title}</option>)}</select></label><label className="filter-control"><span>Min ₹</span><input inputMode="numeric" value={minPrice} onChange={e => setMinPrice(e.target.value.replace(/[^0-9]/g, ""))} placeholder="Any" /></label><label className="filter-control"><span>Max ₹</span><input inputMode="numeric" value={maxPrice} onChange={e => setMaxPrice(e.target.value.replace(/[^0-9]/g, ""))} placeholder="Any" /></label><label className="video-filter"><input type="checkbox" checked={videoOnly} onChange={e => setVideoOnly(e.target.checked)} /> Films</label><label className="sort-control"><span>{filtered.length} pieces</span><select value={sort} onChange={e => setSort(e.target.value)}><option value="featured">Featured</option><option value="price-low">Price: Low to high</option><option value="price-high">Price: High to low</option><option value="name">Name: A–Z</option></select><ChevronDown size={14} /></label></div></div><div className="product-grid listing-grid">{filtered.map(p => <ProductCard key={p.id} product={p} onAdd={onAdd} adding={addingId === p.id} isSaved={savedIds?.has(p.id)} onWishlist={onWishlist} />)}</div>{filtered.length === 0 && <div className="empty-state"><Search size={28} /><h2>No pieces match</h2><p>Try widening the price range, choosing another brand, or clearing Films.</p></div>}</section>;
}

function ProductPage({ products, onAdd }: { products: Product[]; onAdd: (p: Product, quantity?: number) => void }) {
  const [location] = useLocation(); const id = Number(location.split("/").pop()); const product = products.find(p => p.id === id) || products[0]; const [active, setActive] = useState(0); const [quantity, setQuantity] = useState(1);
  if (!product) return <div className="empty-state container"><h2>Piece not found</h2><Link href="/products" className="button button-dark">Back to collection</Link></div>;
  const imgs = imagesOf(product); const discounted = Number(product.discount) > 0;
  const updateQty = (value: string) => { const sanitized = value.replace(/[^0-9]/g, ""); if (sanitized === "") return setQuantity(1); setQuantity(Math.min(product.stock, Math.max(1, Number(sanitized)))); };
  return <section className="detail container"><div className="breadcrumbs"><Link href="/products">Collection</Link><span>/</span><span>{product.name}</span></div><div className="detail-grid"><div className="detail-gallery"><div className="detail-main-image"><img src={imgs[active]} alt={product.name} /><span className="gallery-count">0{active + 1} / 0{imgs.length}</span></div><div className="thumbnail-row">{imgs.map((img, index) => <button key={img} className={active === index ? "active" : ""} onClick={() => setActive(index)}><img src={img} alt={`${product.name} view ${index + 1}`} /></button>)}</div></div>{product.videoUrl && <div className="detail-video"><video controls preload="metadata" poster={product.videoPoster || undefined} src={product.videoUrl} /><span className="video-caption">PRODUCT FILM / 16:9</span></div>}<div className="detail-info"><p className="eyebrow">{product.collection === "men" ? "MEN'S COLLECTION" : "WOMEN'S COLLECTION"}</p><h1>{product.name}</h1><p className="detail-subtitle">{product.shortDescription}</p><div className="detail-price">{discounted && <span className="original-price">{money(product.price)}</span>}<strong>{money(finalPrice(product))}</strong>{discounted && <span className="discount-note">-{Number(product.discount)}% today</span>}</div><div className="detail-rule" /><p className="detail-description">{product.description}</p><div className="detail-specs"><div><span>Case</span><strong>Stainless steel</strong></div><div><span>Movement</span><strong>Automatic</strong></div><div><span>Water resistance</span><strong>5 ATM</strong></div></div><div className="stock-callout"><span className="stock-dot" /><strong>{product.stock < 8 ? `Only ${product.stock} remaining` : `${product.stock} in stock`}</strong><span>Ships in 1–2 business days</span></div><div className="detail-actions"><div className="quantity-control"><button onClick={() => setQuantity(Math.max(1, quantity - 1))}>−</button><input value={quantity} inputMode="numeric" pattern="[0-9]*" onChange={e => updateQty(e.target.value)} aria-label="Quantity" /><button onClick={() => setQuantity(Math.min(product.stock, quantity + 1))}>+</button></div><button className="button button-dark add-detail" onClick={() => onAdd(product, quantity)}><ShoppingBag size={17} /> Add to bag</button></div><p className="detail-payment"><LockKeyhole size={14} /> Secure checkout with Razorpay</p></div></div></section>;
}


function WishlistPage({ products, onAdd, addingId, savedIds, onWishlist }: { products: Product[]; onAdd: (p: Product) => void; addingId?: number | null; savedIds: Set<number>; onWishlist: (p: Product) => void }) { const { data: session } = trpc.store.session.useQuery(); const saved = products.filter(product => savedIds.has(product.id)); if (!session) return <div className="auth-wall container"><Heart size={28} /><p className="eyebrow">YOUR WISHLIST</p><h1>Keep the pieces<br /><em>you love.</em></h1><p>Sign in with your email and password to save watches for later.</p><Link href="/account" className="button button-dark">Sign in to wishlist <ArrowRight size={16} /></Link></div>; return <section className="listing container"><div className="listing-heading"><div><p className="eyebrow">YOUR WISHLIST</p><h1>Pieces worth<br /><em>remembering.</em></h1></div><p className="listing-note">Saved watches stay with your account, ready whenever the time feels right.</p></div>{saved.length === 0 ? <div className="empty-state"><Heart size={28} /><h2>Your wishlist is empty</h2><p>Tap the heart on any watch to save it here.</p><Link href="/products" className="button button-dark">Explore timepieces <ArrowRight size={16} /></Link></div> : <div className="product-grid listing-grid">{saved.map(product => <ProductCard key={product.id} product={product} onAdd={onAdd} adding={addingId === product.id} isSaved onWishlist={onWishlist} />)}</div>}</section>; }

function CartPage({ cart, setCart, onCheckout, onQuantityChange }: { cart: CartItem[]; setCart: (items: CartItem[]) => void; onCheckout: () => void; onQuantityChange?: (items: CartItem[]) => void }) {
  const subtotal = cart.reduce((sum, item) => sum + finalPrice(item.product) * item.quantity, 0); const savings = cart.reduce((sum, item) => sum + (Number(item.product.price) - finalPrice(item.product)) * item.quantity, 0);
  const update = (id: number, value: string) => { const cleaned = value.replace(/[^0-9]/g, ""); const qty = Math.max(1, Math.min(cart.find(item => item.product.id === id)?.product.stock || 1, Number(cleaned) || 1)); const next = cart.map(item => item.product.id === id ? { ...item, quantity: qty } : item); (onQuantityChange || setCart)(next); };
  return <section className="cart-page container"><div className="breadcrumbs"><Link href="/products">Continue shopping</Link><span>/</span><span>Your bag</span></div><div className="cart-heading"><div><p className="eyebrow">YOUR SELECTION</p><h1>Your <em>bag.</em></h1></div><span>{cart.length} {cart.length === 1 ? "piece" : "pieces"}</span></div>{cart.length === 0 ? <div className="empty-state"><ShoppingBag size={36} /><h2>Your bag is waiting</h2><p>Find the piece that feels like yours.</p><Link href="/products" className="button button-dark">Explore watches <ArrowRight size={16} /></Link></div> : <div className="cart-grid"><div className="cart-items">{cart.map(item => <div className="cart-row" key={item.product.id}><img src={imagesOf(item.product)[0]} alt={item.product.name} /><div className="cart-row-info"><p className="eyebrow">{item.product.collection === "men" ? "MEN'S COLLECTION" : "WOMEN'S COLLECTION"}</p><h3>{item.product.name}</h3><p>{item.product.shortDescription}</p><div className="cart-meta"><div className="quantity-control small"><button onClick={() => update(item.product.id, String(item.quantity - 1))}>−</button><input value={item.quantity} onChange={e => update(item.product.id, e.target.value)} inputMode="numeric" pattern="[0-9]*" aria-label={`Quantity of ${item.product.name}`} /><button onClick={() => update(item.product.id, String(item.quantity + 1))}>+</button></div><button className="remove-button" onClick={() => setCart(cart.filter(i => i.product.id !== item.product.id))}><Trash2 size={14} /> Remove</button></div></div><strong className="cart-line-price">{money(finalPrice(item.product) * item.quantity)}</strong></div>)}</div><aside className="order-summary"><p className="eyebrow">ORDER SUMMARY</p><div><span>Subtotal</span><strong>{money(subtotal)}</strong></div><div><span>Delivery</span><strong>Complimentary</strong></div>{savings > 0 && <div className="summary-saving"><span>You save</span><strong>−{money(savings)}</strong></div>}<div className="summary-total"><span>Total</span><strong>{money(subtotal)}</strong></div><button className="button button-dark full-button" onClick={onCheckout}>Continue to checkout <ArrowRight size={16} /></button><p className="summary-note"><LockKeyhole size={13} /> Encrypted and secure checkout</p></aside></div>}</section>;
}

function AuthModal({ onClose, onDone, adminOnly = false }: { onClose: () => void; onDone: () => void; adminOnly?: boolean }) {
  const [mode, setMode] = useState<"login" | "signup">("login"); const [email, setEmail] = useState(adminOnly ? "owner@horologe.com" : ""); const [password, setPassword] = useState(adminOnly ? "horologe-demo" : ""); const utils = trpc.useUtils();
  const login = trpc.store.auth.login.useMutation({ onSuccess: async (data) => { if (data.sessionToken) sessionStorage.setItem("horologe-session", data.sessionToken); await utils.store.session.invalidate(); toast.success("Welcome back"); onDone(); }, onError: error => toast.error(error.message) });
  const signup = trpc.store.auth.signup.useMutation({ onSuccess: async (data) => { if (data.sessionToken) sessionStorage.setItem("horologe-session", data.sessionToken); await utils.store.session.invalidate(); toast.success("Account created"); onDone(); }, onError: error => toast.error(error.message) });
  const submit = (e: React.FormEvent) => { e.preventDefault(); if (mode === "login") login.mutate({ email, password }); else signup.mutate({ email, password }); };
  return <div className="modal-backdrop" onMouseDown={e => e.target === e.currentTarget && onClose()}><div className="auth-modal"><button className="modal-close" onClick={onClose}><X size={18} /></button><div className="auth-mark">H</div><p className="eyebrow">{adminOnly ? "OWNER ACCESS" : "YOUR HOROLOGE ACCOUNT"}</p><h2>{adminOnly ? "Welcome back, owner." : mode === "login" ? "Good to see you." : "Begin your collection."}</h2><p className="auth-intro">{adminOnly ? "Sign in with the owner email and password to manage your store." : "Email and password only. No social logins, no distractions."}</p>{!adminOnly && <div className="auth-tabs"><button className={mode === "login" ? "active" : ""} onClick={() => setMode("login")}>Sign in</button><button className={mode === "signup" ? "active" : ""} onClick={() => setMode("signup")}>Create account</button></div>}<form onSubmit={submit}><label>Email address<input type="email" value={email} onChange={e => setEmail(e.target.value)} required autoComplete="email" /></label><label>Password<input type="password" value={password} onChange={e => setPassword(e.target.value)} minLength={mode === "signup" ? 8 : 1} required autoComplete={mode === "login" ? "current-password" : "new-password"} /></label><button className="button button-dark full-button" disabled={login.isPending || signup.isPending}>{login.isPending || signup.isPending ? "Checking…" : adminOnly ? "Enter admin panel" : mode === "login" ? "Sign in" : "Create account"}</button></form>{adminOnly && <p className="demo-hint">Demo owner access is prefilled for preview. Replace with OWNER_EMAIL and OWNER_PASSWORD in production.</p>}</div></div>;
}

function CheckoutPage({ cart, onComplete }: { cart: CartItem[]; onComplete: () => void }) {
  const { data: session } = trpc.store.session.useQuery();
  const { data: checkoutConfig } = trpc.store.checkout.config.useQuery();
  const createPayment = trpc.store.checkout.createPaymentOrder.useMutation();
  const createOrder = trpc.store.checkout.createOrder.useMutation();
  const confirmPayment = trpc.store.checkout.confirmPayment.useMutation();
  const [email, setEmail] = useState(session?.email || "");
  const [busy, setBusy] = useState(false);
  const [address, setAddress] = useState({ fullName: "", line1: "", line2: "", city: "", state: "", postalCode: "", country: "India", phone: "" });
  const subtotal = cart.reduce((sum, item) => sum + finalPrice(item.product) * item.quantity, 0);
  const taxRate = checkoutConfig?.taxRate ?? 0.18;
  const tax = subtotal * taxRate;
  const total = subtotal + tax;
  const setAddressField = (field: keyof typeof address, value: string) => setAddress(previous => ({ ...previous, [field]: value }));
  useEffect(() => { if (session?.email) setEmail(session.email); }, [session?.email]);
  if (!session) return <div className="auth-wall container"><LockKeyhole size={28} /><p className="eyebrow">CHECKOUT</p><h1>Sign in to<br /><em>continue.</em></h1><p>Your account keeps orders, stock updates, and refund requests in one place.</p><Link href="/account" className="button button-dark">Sign in or create account <ArrowRight size={16} /></Link></div>;
  const placeOrder = async (e: React.FormEvent) => { e.preventDefault(); if (!cart.length) return; setBusy(true); try { const order = await createOrder.mutateAsync({ email, items: cart.map(item => ({ productId: item.product.id, quantity: item.quantity })), shippingAddress: address }); const payment = await createPayment.mutateAsync({ orderId: order.id }); if (payment.configured && payment.orderId) { await loadRazorpay(); await new Promise<void>((resolve, reject) => { const checkout = new (window as any).Razorpay({ key: payment.keyId, amount: Math.round(payment.amount * 100), currency: "INR", name: "Horologe", description: "Considered timepieces", order_id: payment.orderId, handler: async (response: any) => { try { await confirmPayment.mutateAsync({ orderId: order.id, paymentId: response.razorpay_payment_id, razorpayOrderId: response.razorpay_order_id, razorpaySignature: response.razorpay_signature }); resolve(); } catch (error) { reject(error); } }, modal: { ondismiss: () => reject(new Error("Payment was cancelled")) } }); checkout.open(); }); } else { await confirmPayment.mutateAsync({ orderId: order.id, paymentId: `pay_demo_${Date.now()}` }); } toast.success("Payment successful. Your order is confirmed."); onComplete(); } catch (error) { toast.error(error instanceof Error ? error.message : "Payment could not be completed"); } finally { setBusy(false); } };
  return <section className="checkout container"><div className="breadcrumbs"><Link href="/cart">Your bag</Link><span>/</span><span>Checkout</span></div><div className="checkout-heading"><p className="eyebrow">SECURE CHECKOUT</p><h1>Almost <em>yours.</em></h1><p>Complete your order securely with Razorpay.</p></div><div className="checkout-grid"><form className="checkout-form" onSubmit={placeOrder}><div className="form-section"><div className="form-section-head"><span>01</span><div><h3>Contact details</h3><p>We’ll use this email for your order updates.</p></div></div><label>Email address<input type="email" value={email} onChange={e => setEmail(e.target.value)} required /></label></div><div className="form-section"><div className="form-section-head"><span>02</span><div><h3>Shipping address</h3><p>Where should we send your timepieces?</p></div></div><div className="form-two"><label>Full name<input value={address.fullName} onChange={e => setAddressField("fullName", e.target.value)} required /></label><label>Phone<input type="tel" value={address.phone} onChange={e => setAddressField("phone", e.target.value.replace(/[^+0-9]/g, ""))} required /></label></div><label>Address line 1<input value={address.line1} onChange={e => setAddressField("line1", e.target.value)} required /></label><label>Address line 2 <span className="field-optional">Optional</span><input value={address.line2} onChange={e => setAddressField("line2", e.target.value)} /></label><div className="form-three"><label>City<input value={address.city} onChange={e => setAddressField("city", e.target.value)} required /></label><label>State<input value={address.state} onChange={e => setAddressField("state", e.target.value)} required /></label><label>PIN code<input inputMode="numeric" pattern="[0-9]{6}" value={address.postalCode} onChange={e => setAddressField("postalCode", e.target.value.replace(/[^0-9]/g, "").slice(0, 6))} required /></label></div></div><div className="form-section"><div className="form-section-head"><span>03</span><div><h3>Payment</h3><p>Protected by Razorpay’s secure payment gateway.</p></div></div><div className="payment-placeholder"><CreditCard size={22} /><div><strong>Razorpay</strong><span>Cards, UPI, net banking and wallets</span></div><Check size={18} /></div></div><button className="button button-dark full-button" disabled={busy}>{busy ? "Processing securely…" : `Pay ${money(total)}`} <ArrowRight size={16} /></button></form><aside className="checkout-summary"><p className="eyebrow">YOUR ORDER</p>{cart.map(item => <div className="checkout-item" key={item.product.id}><img src={imagesOf(item.product)[0]} alt="" /><div><strong>{item.product.name}</strong><span>Qty {item.quantity}</span></div><b>{money(finalPrice(item.product) * item.quantity)}</b></div>)}<div><span>Subtotal</span><strong>{money(subtotal)}</strong></div><div><span>GST ({Math.round(taxRate * 100)}%)</span><strong>{money(tax)}</strong></div><div className="summary-total"><span>Total</span><strong>{money(total)}</strong></div><p className="checkout-trust"><LockKeyhole size={13} /> Your payment information is encrypted end to end.</p></aside></div></section>;
}

function AccountPage({ onClose }: { onClose: () => void }) { const { data: session } = trpc.store.session.useQuery(); const { data: orders = [] as any[] } = trpc.store.checkout.myOrders.useQuery(undefined, { enabled: Boolean(session) }); const refund = trpc.store.checkout.requestRefund.useMutation({ onSuccess: () => toast.success("Refund request submitted"), onError: e => toast.error(e.message) }); const logout = trpc.store.auth.logout.useMutation({ onSuccess: () => { sessionStorage.removeItem("horologe-session"); window.location.href = "/"; } }); if (!session) return <AuthModal onClose={onClose} onDone={onClose} />; return <section className="account-page container"><p className="eyebrow">YOUR ACCOUNT</p><h1>Welcome, <em>{session.name.split(" ")[0]}.</em></h1><div className="account-card"><div className="account-avatar">{initials(session.name)}</div><div><strong>{session.name}</strong><span>{session.email}</span><small>Email and password account</small><Link className="row-link" href="/wishlist">View wishlist <Heart size={13} /></Link></div><button className="button button-outline" onClick={() => logout.mutate()}>Sign out <LogOut size={15} /></button></div><div className="account-order-list"><div className="account-section-head"><div><p className="eyebrow">ORDER HISTORY</p><h2>Your orders</h2></div><span>{orders.length} total</span></div>{orders.length === 0 ? <div className="account-empty"><Package size={20} /><p>Your paid orders will appear here.</p></div> : orders.map(order => <div className="account-order" key={order.id}><div><strong>{order.orderNumber}</strong><span>{new Date(order.createdAt).toLocaleDateString()} · {order.customerEmail}</span></div><b>{money(order.total)}</b><span className={`status-tag status-${order.status}`}>{order.status}</span>{order.trackingNumber && <a className="row-link" href={order.trackingUrl || "#"} target="_blank" rel="noreferrer">Track {order.trackingNumber}</a>}{["paid", "packed", "shipped", "delivered"].includes(order.status) && <button className="row-link" onClick={() => refund.mutate({ orderId: order.id, amount: Number(order.total), reason: "Customer refund request" })}>Request refund</button>}</div>)}</div></section>; }

function AdminApp() {
  const { data: session, isLoading } = trpc.store.session.useQuery(); const [showLogin, setShowLogin] = useState(false); const [tab, setTab] = useState<AdminTab>("overview");
  useEffect(() => { if (!isLoading && (!session || session.role !== "admin")) setShowLogin(true); }, [isLoading, session]);
  if (showLogin || !session || session.role !== "admin") return <><AdminLoginHeader /><AuthModal adminOnly onClose={() => window.location.href = "/"} onDone={() => window.location.reload()} /></>;
  return <AdminShell tab={tab} setTab={setTab} />;
}

function AdminLoginHeader() { return <div className="admin-login-header"><Link href="/" className="wordmark"><span className="wordmark-mark">H</span><span>HOROLOGE</span></Link><span>Owner portal / secure access</span></div>; }

function AdminShell({ tab, setTab }: { tab: AdminTab; setTab: (tab: AdminTab) => void }) {
  const logout = trpc.store.auth.logout.useMutation({ onSuccess: () => { window.location.href = "/"; } }); const { data: dashboard, refetch: refetchDashboard } = trpc.store.admin.dashboard.useQuery(); const { data: products = [] as Product[], refetch: refetchProducts } = trpc.store.admin.products.useQuery(); const { data: orders = [] as any[], refetch: refetchOrders } = trpc.store.admin.orders.useQuery(); const { data: refunds = [] as any[], refetch: refetchRefunds } = trpc.store.admin.refunds.useQuery(); const { data: brands = [] as Brand[], refetch: refetchBrands } = trpc.store.admin.brands.useQuery(); const [editing, setEditing] = useState<Product | null>(null); const [showForm, setShowForm] = useState(false);
  const refresh = () => { refetchDashboard(); refetchProducts(); refetchOrders(); refetchRefunds(); refetchBrands(); };
  return <div className="admin-shell"><aside className="admin-sidebar"><div className="admin-side-top"><Link href="/" className="wordmark"><span className="wordmark-mark">H</span><span>HOROLOGE</span></Link><span className="admin-pill">OWNER</span></div><div className="admin-side-label">Workspace</div><nav>{([ ["overview", Gauge, "Overview"], ["products", ShoppingBag, "Products"], ["orders", Package, "Orders"], ["refunds", FileText, "Refunds"], ["brands", Sparkles, "Brands"] ] as const).map(([key, Icon, label]) => <button key={key} className={tab === key ? "active" : ""} onClick={() => setTab(key)}><Icon size={17} />{label}{key === "orders" && (orders as any[]).length > 0 && <b>{(orders as any[]).length}</b>}</button>)}</nav><div className="admin-side-bottom"><div className="admin-owner"><div className="admin-avatar">H</div><div><strong>Store owner</strong><span>owner@horologe.com</span></div></div><button className="admin-logout" onClick={() => logout.mutate()}><LogOut size={15} /> Sign out</button></div></aside><main className="admin-main"><div className="admin-topbar"><div><span className="admin-breadcrumb">Horologe / {tab}</span><h1>{tab === "overview" ? "Good morning, owner." : tab[0].toUpperCase() + tab.slice(1)}</h1></div><div className="admin-top-actions"><Link href="/" className="button button-outline">View store <ArrowRight size={15} /></Link>{tab === "products" && <button className="button button-dark" onClick={() => { setEditing(null); setShowForm(true); }}><Plus size={16} /> Add product</button>}</div></div>{tab === "overview" && <AdminOverview dashboard={dashboard} products={products as Product[]} orders={orders as any[]} />} {tab === "products" && <AdminProducts products={products as Product[]} brands={brands as Brand[]} onEdit={product => { setEditing(product); setShowForm(true); }} onRefresh={refresh} />} {tab === "orders" && <AdminOrders orders={orders as any[]} onRefresh={refresh} />} {tab === "refunds" && <AdminRefunds refunds={refunds as any[]} onRefresh={refresh} />} {tab === "brands" && <AdminBrands brands={brands as Brand[]} onRefresh={refresh} />} {showForm && <ProductForm product={editing} brands={brands as Brand[]} onClose={() => setShowForm(false)} onSaved={() => { setShowForm(false); refresh(); }} />}</main></div>;
}

function AdminOverview({ dashboard, products, orders }: { dashboard?: { products: number; orders: number; refunds: number; revenue: number }; products: Product[]; orders: any[] }) { return <div className="admin-content"><div className="metric-grid"><Metric icon={ShoppingBag} label="Live products" value={dashboard?.products ?? products.length} detail="Across both collections" /><Metric icon={Package} label="Orders" value={dashboard?.orders ?? orders.length} detail="All-time order count" /><Metric icon={UsersRound} label="Revenue" value={money(dashboard?.revenue ?? 0)} detail="Before refunds" /><Metric icon={Gauge} label="Low stock" value={products.filter(p => p.stock < 8).length} detail="Needs your attention" /></div><div className="admin-panels"><div className="admin-panel"><div className="panel-heading"><div><span className="admin-label">CATALOG HEALTH</span><h2>Inventory at a glance</h2></div><button onClick={() => window.location.href = "/admin/products"}>Manage <ArrowRight size={14} /></button></div>{products.slice(0, 5).map(p => <div className="inventory-row" key={p.id}><img src={imagesOf(p)[0]} alt="" /><div><strong>{p.name}</strong><span>{p.collection} collection</span></div><div className="inventory-stock"><span className={p.stock < 8 ? "low" : ""}>{p.stock}</span><small>in stock</small></div></div>)}</div><div className="admin-panel dark-panel"><span className="admin-label">OPERATIONS</span><h2>Keep every hour moving.</h2><p>Review orders, update stock manually, and keep the collection feeling intentional.</p><button className="button button-light" onClick={() => window.location.href = "/admin/orders"}>Review orders <ArrowRight size={15} /></button></div></div></div>; }
function Metric({ icon: Icon, label, value, detail }: { icon: any; label: string; value: string | number; detail: string }) { return <div className="metric-card"><div className="metric-icon"><Icon size={18} /></div><span>{label}</span><strong>{value}</strong><small>{detail}</small></div>; }

function AdminProducts({ products, brands, onEdit, onRefresh }: { products: Product[]; brands: Brand[]; onEdit: (p: Product) => void; onRefresh: () => void }) { const setStock = trpc.store.admin.setStock.useMutation({ onSuccess: () => { toast.success("Stock updated"); onRefresh(); }, onError: e => toast.error(e.message) }); const del = trpc.store.admin.deleteProduct.useMutation({ onSuccess: () => { toast.success("Product deleted"); onRefresh(); }, onError: e => toast.error(e.message) }); return <div className="admin-content"><div className="table-toolbar"><div><span className="admin-label">CATALOG</span><p>{products.length} products / {brands.length} brands</p></div><div className="table-search"><Search size={15} /><input placeholder="Search products" /></div></div><div className="data-table"><div className="table-head"><span>Product</span><span>Collection</span><span>Price</span><span>Stock</span><span>Status</span><span /></div>{products.length === 0 ? <div className="table-empty">No products yet. Add your first timepiece to begin.</div> : products.map(p => <div className="table-row" key={p.id}><div className="table-product"><img src={imagesOf(p)[0]} alt="" /><div><strong>{p.name}</strong><span>{p.shortDescription}</span></div></div><span className="capitalize">{p.collection}</span><span>{money(finalPrice(p))}</span><div className="stock-editor"><input value={p.stock} min={1} max={1000} inputMode="numeric" pattern="[0-9]*" onChange={e => { const value = e.target.value.replace(/[^0-9]/g, ""); if (value) setStock.mutate({ id: p.id, stock: Math.max(1, Math.min(1000, Number(value))) }); }} /><small>/ 1000</small></div><span className={`status-tag ${p.stock < 8 ? "status-low" : "status-live"}`}>{p.stock < 8 ? "Low stock" : "Live"}</span><div className="row-actions"><button onClick={() => onEdit(p)}>Edit</button><button className="danger-text" onClick={() => del.mutate({ id: p.id })}><Trash2 size={14} /></button></div></div>)}</div></div>; }

function AdminOrders({ orders, onRefresh }: { orders: any[]; onRefresh: () => void }) {
  const update = trpc.store.admin.updateOrder.useMutation({ onSuccess: () => { toast.success("Order updated"); onRefresh(); }, onError: e => toast.error(e.message) });
  return <div className="admin-content"><div className="table-toolbar"><div><span className="admin-label">ORDER MANAGEMENT</span><p>{orders.length} orders · status and fulfillment tracking</p></div></div><div className="data-table"><div className="table-head"><span>Order</span><span>Customer</span><span>Total</span><span>Status</span><span>Tracking</span><span>Placed</span></div>{orders.length === 0 ? <div className="table-empty">Orders will appear here after a successful Razorpay payment.</div> : orders.map(order => <OrderRow key={order.id} order={order} update={update} />)}</div></div>;
}

function OrderRow({ order, update }: { order: any; update: ReturnType<typeof trpc.store.admin.updateOrder.useMutation> }) {
  const [trackingNumber, setTrackingNumber] = useState(order.trackingNumber || "");
  const [trackingUrl, setTrackingUrl] = useState(order.trackingUrl || "");
  const saveTracking = () => update.mutate({ id: order.id, status: order.status, trackingNumber, trackingUrl: trackingUrl || undefined });
  return <div className="table-row order-management-row"><div><strong>{order.orderNumber}</strong><span className="muted">#{order.id}</span></div><span>{order.customerEmail}</span><strong>{money(order.total)}</strong><select className="status-select" value={order.status} onChange={e => update.mutate({ id: order.id, status: e.target.value as any, trackingNumber, trackingUrl: trackingUrl || undefined })}><option>pending</option><option>paid</option><option>packed</option><option>shipped</option><option>delivered</option><option>cancelled</option><option>refunded</option></select><div className="tracking-editor"><input value={trackingNumber} onChange={e => setTrackingNumber(e.target.value)} placeholder="AWB / tracking" /><input type="url" value={trackingUrl} onChange={e => setTrackingUrl(e.target.value)} placeholder="Tracking URL" /><button className="row-link" onClick={saveTracking}>Save</button></div><span className="muted">{new Date(order.createdAt).toLocaleDateString()}</span></div>;
}

function AdminRefunds({ refunds, onRefresh }: { refunds: any[]; onRefresh: () => void }) { const update = trpc.store.admin.updateRefund.useMutation({ onSuccess: () => { toast.success("Refund updated"); onRefresh(); } }); return <div className="admin-content"><div className="table-toolbar"><div><span className="admin-label">REFUND QUEUE</span><p>Review requests from customers</p></div></div><div className="data-table"><div className="table-head"><span>Request</span><span>Order</span><span>Amount</span><span>Reason</span><span>Status</span><span /></div>{refunds.length === 0 ? <div className="table-empty">No refund requests yet.</div> : refunds.map(refund => <div className="table-row" key={refund.id}><strong>RF-{refund.id.toString().padStart(4, "0")}</strong><span>Order #{refund.orderId}</span><strong>{money(refund.amount)}</strong><span className="truncate">{refund.reason}</span><select className="status-select" value={refund.status} onChange={e => update.mutate({ id: refund.id, status: e.target.value as any })}><option>requested</option><option>approved</option><option>processed</option><option>rejected</option></select><span className="muted">{new Date(refund.createdAt).toLocaleDateString()}</span></div>)}</div></div>; }
function AdminBrands({ brands, onRefresh }: { brands: Brand[]; onRefresh: () => void }) { const create = trpc.store.admin.createBrand.useMutation({ onSuccess: () => { toast.success("Brand created"); onRefresh(); }, onError: e => toast.error(e.message) }); const update = trpc.store.admin.updateBrand.useMutation({ onSuccess: () => { toast.success("Brand updated"); setEditing(null); onRefresh(); }, onError: e => toast.error(e.message) }); const del = trpc.store.admin.deleteBrand.useMutation({ onSuccess: () => { toast.success("Brand deleted"); onRefresh(); }, onError: e => toast.error(e.message) }); const [editing, setEditing] = useState<Brand | null>(null); const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); const [image, setImage] = useState(""); const reset = () => { setTitle(""); setDescription(""); setImage(""); setEditing(null); }; const submit = (e: React.FormEvent) => { e.preventDefault(); if (editing) update.mutate({ id: editing.id, title, description, image }); else create.mutate({ title, description, image }); reset(); }; return <div className="admin-content"><div className="brand-layout"><div className="admin-panel"><div className="panel-heading"><div><span className="admin-label">{editing ? "EDIT BRAND" : "NEW BRAND"}</span><h2>{editing ? "Refine the label" : "Add a label"}</h2></div></div><form className="brand-form" onSubmit={submit}><label>Title<input value={title} onChange={e => setTitle(e.target.value)} maxLength={250} required /></label><label>Description<textarea value={description} onChange={e => setDescription(e.target.value)} maxLength={700} required /></label><div className="media-field"><label>Image URL (1:1)<input type="url" value={image} onChange={e => setImage(e.target.value)} required placeholder="https://… or /storage/…" /></label><MediaUpload label="Upload optimized 1:1 brand image" accept="image/jpeg,image/png,image/webp" onUploaded={url => setImage(url)} /></div><div className="form-actions"><button type="button" className="button button-outline" onClick={reset}>Clear</button><button className="button button-dark">{editing ? "Save brand" : "Create brand"} <Plus size={15} /></button></div></form></div><div className="brand-list"><div className="panel-heading"><div><span className="admin-label">BRAND DIRECTORY</span><h2>{brands.length} brands</h2></div></div>{brands.map(b => <div className="brand-row" key={b.id}><img src={b.image} alt="" /><div><strong>{b.title}</strong><span>{b.description}</span></div><button className="row-link" onClick={() => { setEditing(b); setTitle(b.title); setDescription(b.description); setImage(b.image); }}>Edit</button><button className="danger-text row-link" onClick={() => del.mutate({ id: b.id })}><Trash2 size={14} /></button></div>)}</div></div></div>; }

function ProductForm({ product, brands, onClose, onSaved }: { product: Product | null; brands: Brand[]; onClose: () => void; onSaved: () => void }) { const create = trpc.store.admin.createProduct.useMutation({ onSuccess: onSaved, onError: e => toast.error(e.message) }); const update = trpc.store.admin.updateProduct.useMutation({ onSuccess: onSaved, onError: e => toast.error(e.message) }); const firstImages = product ? imagesOf(product) : [""]; const [form, setForm] = useState({ brandId: product?.brandId || brands[0]?.id || 1, collection: product?.collection || "men", name: product?.name || "", shortDescription: product?.shortDescription || "", description: product?.description || "", images: firstImages, videoUrl: product?.videoUrl || "", videoPoster: product?.videoPoster || "", price: Number(product?.price || 0), discount: Number(product?.discount || 0), stock: product?.stock || 1 }); const set = (key: string, value: any) => setForm(prev => ({ ...prev, [key]: value })); const submit = (e: React.FormEvent) => { e.preventDefault(); const rawImages = form.images.filter(Boolean); if (rawImages.length > 5) return toast.error("Use at most 5 product images"); const images = rawImages; if (!images.length) return toast.error("Add at least one 4:5 product image URL"); if (product) update.mutate({ ...form, collection: form.collection as "men" | "women", images, id: product.id }); else create.mutate({ ...form, collection: form.collection as "men" | "women", images }); }; return <div className="modal-backdrop"><div className="product-modal"><div className="modal-header"><div><span className="admin-label">{product ? "EDIT PRODUCT" : "NEW PRODUCT"}</span><h2>{product ? "Refine the details." : "Add a timepiece."}</h2></div><button className="modal-close" onClick={onClose}><X size={18} /></button></div><form className="product-form" onSubmit={submit}><div className="form-two"><label>Product name<input value={form.name} onChange={e => set("name", e.target.value)} required maxLength={180} /></label><label>Brand<select value={form.brandId} onChange={e => set("brandId", Number(e.target.value))}>{brands.map(b => <option key={b.id} value={b.id}>{b.title}</option>)}</select></label></div><div className="form-two"><label>Collection<select value={form.collection} onChange={e => set("collection", e.target.value)}><option value="men">Men</option><option value="women">Women</option></select></label><label>Short description<input value={form.shortDescription} onChange={e => set("shortDescription", e.target.value)} required maxLength={180} /></label></div><label>Full description<textarea value={form.description} onChange={e => set("description", e.target.value)} required /></label><div className="form-three"><label>Price (₹)<input type="number" min="0" value={form.price} onChange={e => set("price", Number(e.target.value))} required /></label><label>Discount (%)<input type="number" min="0" max="100" value={form.discount} onChange={e => set("discount", Number(e.target.value))} required /></label><label>Stock (1–1000)<input type="text" inputMode="numeric" pattern="[0-9]*" value={form.stock} onChange={e => { const clean = e.target.value.replace(/[^0-9]/g, ""); set("stock", Math.max(1, Math.min(1000, Number(clean) || 1))); }} required /></label></div><div className="media-field"><label>Product images (4:5 ratio URLs, 1–5 only)<input value={form.images.join(",")} onChange={e => set("images", e.target.value.split(",").map(item => item.trim()).slice(0, 5))} placeholder="Paste comma-separated image URLs" /></label><MediaUpload label="Upload optimized 4:5 product image" accept="image/jpeg,image/png,image/webp" onUploaded={url => { if (form.images.filter(Boolean).length >= 5) toast.error("Use at most 5 product images"); else set("images", [...form.images.filter(Boolean), url]); }} /></div><div className="form-two"><div className="media-field"><label>Product film URL (16:9, leave blank to remove)<input type="url" value={form.videoUrl} onChange={e => set("videoUrl", e.target.value)} placeholder="https://…/film.mp4 or /storage/…" /></label><MediaUpload label="Upload horizontal 16:9 video" accept="video/mp4,video/webm,video/quicktime" onUploaded={url => set("videoUrl", url)} /></div><div className="media-field"><label>Video poster URL (16:9)<input type="url" value={form.videoPoster} onChange={e => set("videoPoster", e.target.value)} placeholder="https://…/poster.jpg" /></label><MediaUpload label="Upload 16:9 video poster" accept="image/jpeg,image/png,image/webp" onUploaded={url => set("videoPoster", url)} /></div></div><div className="form-actions"><button type="button" className="button button-outline" onClick={onClose}>Cancel</button><button className="button button-dark">{product ? "Save changes" : "Create product"} <ArrowRight size={15} /></button></div></form></div></div>; }

function StoreApp() { const [location, setLocation] = useLocation(); const [cart, setCartState] = useState<CartItem[]>([]); const [accountOpen, setAccountOpen] = useState(false); const [addingId, setAddingId] = useState<number | null>(null); const [cartUpdating, setCartUpdating] = useState(false); const utils = trpc.useUtils(); const { data: session } = trpc.store.session.useQuery(); const { data: productData = [] } = trpc.store.catalog.products.useQuery({ collection: "all" }); const { data: brandData = [] } = trpc.store.catalog.brands.useQuery(); const { data: wishlistData = [] } = trpc.store.wishlist.list.useQuery(undefined, { enabled: Boolean(session) }); const wishlistToggle = trpc.store.wishlist.toggle.useMutation({ onSuccess: async data => { await utils.store.wishlist.list.invalidate(); toast.success(data.saved ? "Saved to wishlist" : "Removed from wishlist"); }, onError: e => toast.error(e.message) }); const products = productData as Product[]; const brands = brandData as Brand[]; const savedIds = useMemo(() => new Set((wishlistData as Array<{ productId: number }>).map(item => item.productId)), [wishlistData]); useEffect(() => { try { const stored = localStorage.getItem("horologe-cart"); if (stored) setCartState(JSON.parse(stored)); } catch {} }, []); const setCart = (items: CartItem[]) => { setCartState(items); localStorage.setItem("horologe-cart", JSON.stringify(items)); }; const addToCart = (product: Product, quantity = 1) => { if (product.stock === 0) return toast.error("This watch is currently sold out"); setAddingId(product.id); const existing = cart.find(item => item.product.id === product.id); const next = existing ? cart.map(item => item.product.id === product.id ? { ...item, quantity: Math.min(product.stock, item.quantity + quantity) } : item) : [...cart, { product, quantity: Math.min(product.stock, quantity) }]; window.setTimeout(() => { setCart(next); setAddingId(null); toast.success(existing ? product.name + " quantity updated" : product.name + " added to bag"); }, 220); }; const updateCartQuantity = (items: CartItem[]) => { setCartUpdating(true); window.setTimeout(() => { setCart(items); setCartUpdating(false); toast.success("Bag updated"); }, 180); }; const onWishlist = (product: Product) => { if (!session) { toast.info("Sign in to save watches to your wishlist"); setAccountOpen(true); return; } wishlistToggle.mutate({ productId: product.id }); }; useEffect(() => { window.scrollTo({ top: 0, behavior: "smooth" }); }, [location]); return <><StoreHeader cartCount={cart.reduce((sum, i) => sum + i.quantity, 0)} onCart={() => setLocation("/cart")} onAccount={() => setAccountOpen(true)} /><Switch><Route path="/"><HomePage products={products} brands={brands} onAdd={addToCart} addingId={addingId} savedIds={savedIds} onWishlist={onWishlist} /></Route><Route path="/products"><ProductsPage products={products} brands={brands} onAdd={addToCart} addingId={addingId} savedIds={savedIds} onWishlist={onWishlist} /></Route><Route path="/products/:id"><ProductPage products={products} onAdd={addToCart} /></Route><Route path="/wishlist"><WishlistPage products={products} onAdd={addToCart} addingId={addingId} savedIds={savedIds} onWishlist={onWishlist} /></Route><Route path="/cart"><CartPage cart={cart} setCart={setCart} onQuantityChange={updateCartQuantity} onCheckout={() => setLocation("/checkout")} /></Route><Route path="/checkout"><CheckoutPage cart={cart} onComplete={() => { setCart([]); setLocation("/"); }} /></Route><Route path="/account"><AccountPage onClose={() => setLocation("/")} /></Route><Route><div className="empty-state container"><h2>Page not found</h2><Link href="/" className="button button-dark">Back home</Link></div></Route></Switch><Footer />{cartUpdating && <div className="cart-sync-indicator"><span className="button-spinner" /> Updating bag</div>}{accountOpen && <AuthModal onClose={() => setAccountOpen(false)} onDone={() => setAccountOpen(false)} />}</> }

export default function App() { return <ThemeProvider defaultTheme="light"><Toaster position="bottom-right" /><Switch><Route path="/admin"><AdminApp /></Route><Route path="/admin/:rest*"><AdminApp /></Route><Route><StoreApp /></Route></Switch></ThemeProvider>; }
